/**
 * One full card from the model, for the add sheet's Fill with AI and the
 * word screen's Improve with AI.
 */
import { ai as aiApi } from '@/api/endpoints.js';
import type { WordDraft } from '@/db/mutations.js';
import { normalizeHeadword, type LanguageCode } from '@lexpad/core';
import { aiJobFromApi, type AiJobView, type AiReasonCode } from '@/sync/mapping.js';
import { LANGUAGE_NAMES } from '@/features/settings/data.js';
import { getLocale, t } from '@/i18n/index.js';
import { watchJob } from './poll.js';
import { noteRefusal, noteUsage } from './quota.js';

/**
 * A job that ended without a card. `message` is the server's reason in words
 * (or "failed"), `code` its machine code when it sent one.
 */
export class AiJobFailed extends Error {
  readonly code: AiReasonCode | undefined;
  constructor(message: string, code: AiReasonCode | undefined) {
    super(message);
    this.name = 'AiJobFailed';
    this.code = code;
  }
}

/**
 * The reason the API gave for "not recognised" before it sent a code
 * (`publicReason` in lexpad_back internal/app/ai/worker.go, prompt v5). Kept
 * only so this build still tells the case apart against a server that
 * predates `reasonCode`; the code always wins. Remove once every server
 * sends the code.
 */
export const UNRECOGNISED_REASON_TEXT = 'not recognised as a word or phrase';

/**
 * Whether a failed fill said the entry is not a word in the notebook's
 * language: a thrown `AiJobFailed`, or a job that settled as failed.
 */
export function isUnrecognised(cause: unknown): boolean {
  if (cause instanceof AiJobFailed) return unrecognisedReason(cause.code, cause.message);
  if (isFailedJob(cause)) return unrecognisedReason(cause.reasonCode, cause.error ?? '');
  return false;
}

function isFailedJob(value: unknown): value is AiJobView {
  return typeof value === 'object' && value !== null && (value as Partial<AiJobView>).status === 'failed';
}

function unrecognisedReason(code: AiReasonCode | undefined, message: string): boolean {
  if (code !== undefined) return code === 'unrecognised';
  return message.toLowerCase().includes(UNRECOGNISED_REASON_TEXT);
}

/**
 * Whether a failed fill means the AI cannot write these entries at all: not
 * words it knows (`unrecognised`), or cards it wrote unusably twice
 * (`unusable`). Either way asking again at once gets the same answer, so the
 * learner is offered their own meaning, an edit or a delete, never "Try
 * again".
 */
export function isUnwritable(cause: unknown): boolean {
  if (isUnrecognised(cause)) return true;
  if (cause instanceof AiJobFailed) return cause.code === 'unusable';
  return isFailedJob(cause) && cause.reasonCode === 'unusable';
}

/**
 * How many entries a line about unrecognised words names before it says
 * "and N more": a sentence, not a list, so it stays readable on a phone.
 * Display only, which is why it lives here and not in data.
 */
const NAMED_WORDS = 5;

/** The words, quoted and joined the way the interface language joins a list. */
function namedWords(words: readonly string[]): string {
  const quoted = words.slice(0, NAMED_WORDS).map((word) => t('ai.quoted', { word }));
  const more = words.length - quoted.length;
  if (more > 0) quoted.push(t('ai.andMore', { count: more }));
  return new Intl.ListFormat(getLocale(), { style: 'long', type: 'conjunction' }).format(quoted);
}

/**
 * What the learner is told when the AI did not know their entries as words
 * in the notebook's language: calm, naming the entries, and pointing at the
 * spelling or their own meaning. Never "try again", which would only give
 * the same answer.
 */
export function unrecognisedLine(words: readonly string[], language: LanguageCode): string {
  const name = LANGUAGE_NAMES[language];
  const [only] = words;
  if (words.length === 1 && only !== undefined) return t('ai.unrecognised', { word: only, language: name });
  return t('ai.unrecognisedMany', { words: namedWords(words), language: name });
}

/**
 * What the learner is told about the entries a finished job of several left
 * without a card. The server leaves out an entry it does not know as a word
 * (and, rarely, one whose card came back unusable twice) and gives its
 * allowance back; the rest of the job is still filled.
 */
export function skippedLine(words: readonly string[], language: LanguageCode): string {
  return t('ai.skipped', {
    count: words.length,
    words: namedWords(words),
    language: LANGUAGE_NAMES[language],
  });
}

/** The entries a finished job sent but got no card for, in the order they were sent. */
export function missingFrom(sent: readonly string[], cards: readonly { headword: string }[]): string[] {
  const written = new Set(cards.map((card) => normalizeHeadword(card.headword)));
  const seen = new Set<string>();
  return sent.filter((word) => {
    const key = normalizeHeadword(word);
    if (written.has(key) || seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

/** A card the model wrote, with the job that wrote it (what a report names). */
export interface GeneratedCard {
  card: WordDraft;
  jobId: string;
}

/**
 * Asks the model for the card of one entry and waits for it (see
 * `watchJob` for how often it looks). Throws when the job fails, comes back
 * without a card or takes too long, with the server's reason when it gave
 * one.
 */
export async function generateCardWithJob(
  notebookId: string,
  headword: string,
  options: { hint?: string; signal?: AbortSignal } = {},
): Promise<GeneratedCard> {
  let job;
  try {
    job = aiJobFromApi(await aiApi.createCards(notebookId, [headword], options.hint));
  } catch (cause) {
    await noteRefusal(cause);
    throw cause;
  }
  job = await watchJob(job, options.signal === undefined ? {} : { signal: options.signal });
  // A finished job carries the day's count: what the add sheet's "left
  // today" line reads next.
  await noteUsage(job.usage).catch(() => undefined);
  const card = job.cards[0];
  if (job.status !== 'done' || card === undefined)
    throw new AiJobFailed(job.error ?? 'failed', job.reasonCode);
  return { card, jobId: job.id };
}

/** The card alone, for a screen that has nothing to report it from. */
export async function generateCard(
  notebookId: string,
  headword: string,
  options: { hint?: string; signal?: AbortSignal } = {},
): Promise<WordDraft> {
  return (await generateCardWithJob(notebookId, headword, options)).card;
}
